            missing.append(gate_id)
    ok = not missing
    return build_check(
        key="e2e_results_coverage",
        label="E2E results coverage",
        path=path,
        ok=ok,
        detail=f"required={len(required)} missing={', '.join(missing) if missing else 'none'}",
    )


